// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetActivity What the server is doing right now (for the header activity indicator).
	// (GET /activity)
	GetActivity(w http.ResponseWriter, r *http.Request)
	// PlayHistory Recent plays, newest first (admin only).
	// (GET /activity/history)
	PlayHistory(w http.ResponseWriter, r *http.Request, params PlayHistoryParams)

	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Revoke the current session token.
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// PinLogin Sign in by choosing a profile and entering its 4-digit PIN (managed profiles without a PIN need none).
	// (POST /auth/pin)
	PinLogin(w http.ResponseWriter, r *http.Request)
	// ListSignInProfiles Profiles for the "Who's watching?" sign-in screen. Empty when PIN sign-in isn't allowed from the caller's network.
	// (GET /auth/profiles)
	ListSignInProfiles(w http.ResponseWriter, r *http.Request)
	// StartQuickConnect A TV or other device asks to sign in with a code (Quick Connect). It shows the code and polls until someone approves it.
	// (POST /auth/quickconnect)
	StartQuickConnect(w http.ResponseWriter, r *http.Request)
	// AuthorizeQuickConnect Approve a device's Quick Connect code; it signs in as you.
	// (POST /auth/quickconnect/authorize)
	AuthorizeQuickConnect(w http.ResponseWriter, r *http.Request)
	// PollQuickConnect Whether the code has been approved. Once it has, the response carries the sign-in token (only once).
	// (GET /auth/quickconnect/{secret})
	PollQuickConnect(w http.ResponseWriter, r *http.Request, secret string)
	// ListBackups Database backups, newest first (admin only).
	// (GET /backups)
	ListBackups(w http.ResponseWriter, r *http.Request)
	// CreateBackup Back up the database now (admin only).
	// (POST /backups)
	CreateBackup(w http.ResponseWriter, r *http.Request)

	// (DELETE /backups/{name})
	DeleteBackup(w http.ResponseWriter, r *http.Request, name BackupName)
	// DownloadBackup Download a backup file (admin only).
	// (GET /backups/{name})
	DownloadBackup(w http.ResponseWriter, r *http.Request, name BackupName)
	// RestoreBackup Restore a backup (admin only). The server restarts to apply it; the current database is kept as a "pre-restore" backup.
	// (POST /backups/{name}/restore)
	RestoreBackup(w http.ResponseWriter, r *http.Request, name BackupName)
	// ListDevices Signed-in devices. Admins see every user's devices; others see their own.
	// (GET /devices)
	ListDevices(w http.ResponseWriter, r *http.Request)
	// RevokeDevice Sign a device out.
	// (DELETE /devices/{deviceId})
	RevokeDevice(w http.ResponseWriter, r *http.Request, deviceId int64)
	// BrowseFilesystem List directories under the configured browse roots, for the library folder picker (admin only).
	// (GET /filesystem/browse)
	BrowseFilesystem(w http.ResponseWriter, r *http.Request, params BrowseFilesystemParams)
	// HomeHubs Rows for the Home screen (Continue Watching, Recently Added…).
	// (GET /hubs/home)
	HomeHubs(w http.ResponseWriter, r *http.Request)
	// GetImage Artwork resized to a cached width. Responses are immutable (a changed image gets a new id).
	// (GET /images/{artworkId})
	GetImage(w http.ResponseWriter, r *http.Request, artworkId int64, params GetImageParams)

	// (GET /items/{itemId})
	GetItem(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// ListItemChildren Seasons of a show, episodes of a season, albums of an artist, tracks of an album.
	// (GET /items/{itemId}/children)
	ListItemChildren(w http.ResponseWriter, r *http.Request, itemId ItemId, params ListItemChildrenParams)
	// ItemLeaves Playable items under a show, season, artist, album or collection, in play order (for Play all / Shuffle). At most 2,000.
	// (GET /items/{itemId}/leaves)
	ItemLeaves(w http.ResponseWriter, r *http.Request, itemId ItemId, params ItemLeavesParams)
	// SearchMatches Candidate matches for Fix Match (admin only, movies and shows).
	// (GET /items/{itemId}/match)
	SearchMatches(w http.ResponseWriter, r *http.Request, itemId ItemId, params SearchMatchesParams)
	// ApplyMatch Match the item to a specific provider entry and refresh its metadata (admin only).
	// (PUT /items/{itemId}/match)
	ApplyMatch(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// EditItem Edit metadata fields (admin only). Edited fields are locked so agents won't overwrite them.
	// (PATCH /items/{itemId}/metadata)
	EditItem(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// NextItem The episode after this one (Up Next), if any.
	// (GET /items/{itemId}/next)
	NextItem(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// RefreshItem Re-download metadata for a matched movie or show, keeping locked fields (admin only).
	// (POST /items/{itemId}/refresh)
	RefreshItem(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// RelatedItems Similar items from the same library ("More like this"), by shared genres and people.
	// (GET /items/{itemId}/related)
	RelatedItems(w http.ResponseWriter, r *http.Request, itemId ItemId)

	// (DELETE /items/{itemId}/watched)
	MarkUnwatched(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// MarkWatched Mark watched (shows, seasons, artists and albums mark everything inside).
	// (POST /items/{itemId}/watched)
	MarkWatched(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// ListLibraries Libraries visible to the current user.
	// (GET /libraries)
	ListLibraries(w http.ResponseWriter, r *http.Request)
	// CreateLibrary Create a library (admin only).
	// (POST /libraries)
	CreateLibrary(w http.ResponseWriter, r *http.Request)
	// ScanAllLibraries Queue a scan of every library (admin only).
	// (POST /libraries/scan)
	ScanAllLibraries(w http.ResponseWriter, r *http.Request)
	// DeleteLibrary Delete a library and its metadata (admin only). Media files are never touched.
	// (DELETE /libraries/{libraryId})
	DeleteLibrary(w http.ResponseWriter, r *http.Request, libraryId LibraryId)

	// (GET /libraries/{libraryId})
	GetLibrary(w http.ResponseWriter, r *http.Request, libraryId LibraryId)
	// UpdateLibrary Update a library (admin only). Type cannot be changed.
	// (PATCH /libraries/{libraryId})
	UpdateLibrary(w http.ResponseWriter, r *http.Request, libraryId LibraryId)
	// LibraryFilters Values for the library filter bar, and where each letter starts for the A–Z jump bar (title sort).
	// (GET /libraries/{libraryId}/filters)
	LibraryFilters(w http.ResponseWriter, r *http.Request, libraryId LibraryId, params LibraryFiltersParams)
	// ListLibraryItems Top-level items of a library (movies, shows, artists or videos), or all items of a given type.
	// (GET /libraries/{libraryId}/items)
	ListLibraryItems(w http.ResponseWriter, r *http.Request, libraryId LibraryId, params ListLibraryItemsParams)
	// CancelLibraryScan Cancel a queued or running scan (admin only).
	// (DELETE /libraries/{libraryId}/scan)
	CancelLibraryScan(w http.ResponseWriter, r *http.Request, libraryId LibraryId)
	// ScanLibrary Queue a scan of one library (admin only). Returns immediately; poll the library for progress.
	// (POST /libraries/{libraryId}/scan)
	ScanLibrary(w http.ResponseWriter, r *http.Request, libraryId LibraryId)
	// GetLogs Recent server log lines, newest last (admin only).
	// (GET /logs)
	GetLogs(w http.ResponseWriter, r *http.Request, params GetLogsParams)

	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Update your own profile, password, PIN or preferences.
	// (PATCH /me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// GetPerson A person and the items in your libraries they appear in.
	// (GET /people/{personId})
	GetPerson(w http.ResponseWriter, r *http.Request, personId int64)

	// (GET /people/{personId}/photo)
	GetPersonPhoto(w http.ResponseWriter, r *http.Request, personId int64, params GetPersonPhotoParams)
	// BandwidthTest Random bytes for the client to time its download speed (used for automatic remote quality).
	// (GET /playback/bandwidth-test)
	BandwidthTest(w http.ResponseWriter, r *http.Request, params BandwidthTestParams)
	// ListPlaybackSessions Active playback sessions. Administrators see everyone's; others see their own.
	// (GET /playback/sessions)
	ListPlaybackSessions(w http.ResponseWriter, r *http.Request)
	// StartPlayback Start playing an item. The server decides between direct play, direct stream and transcode for this device and network.
	// (POST /playback/sessions)
	StartPlayback(w http.ResponseWriter, r *http.Request)
	// StopPlayback Stop playback. Administrators can stop anyone's session.
	// (DELETE /playback/sessions/{sessionId})
	StopPlayback(w http.ResponseWriter, r *http.Request, sessionId string)
	// ReportPlayback Report position and state (every ~10 seconds, and on pause/seek). Updates resume points and watched status.
	// (PATCH /playback/sessions/{sessionId})
	ReportPlayback(w http.ResponseWriter, r *http.Request, sessionId string)
	// ListPlaylists Your playlists.
	// (GET /playlists)
	ListPlaylists(w http.ResponseWriter, r *http.Request, params ListPlaylistsParams)

	// (POST /playlists)
	CreatePlaylist(w http.ResponseWriter, r *http.Request)

	// (DELETE /playlists/{playlistId})
	DeletePlaylist(w http.ResponseWriter, r *http.Request, playlistId PlaylistId)

	// (GET /playlists/{playlistId})
	GetPlaylist(w http.ResponseWriter, r *http.Request, playlistId PlaylistId)

	// (PATCH /playlists/{playlistId})
	UpdatePlaylist(w http.ResponseWriter, r *http.Request, playlistId PlaylistId)

	// (GET /playlists/{playlistId}/items)
	ListPlaylistItems(w http.ResponseWriter, r *http.Request, playlistId PlaylistId, params ListPlaylistItemsParams)
	// AddPlaylistItems Append items. Shows, seasons, artists and albums add their episodes or tracks.
	// (POST /playlists/{playlistId}/items)
	AddPlaylistItems(w http.ResponseWriter, r *http.Request, playlistId PlaylistId)

	// (DELETE /playlists/{playlistId}/items/{entryId})
	RemovePlaylistItem(w http.ResponseWriter, r *http.Request, playlistId PlaylistId, entryId int64)
	// MovePlaylistItem Move an entry to just after another one (or to the top when afterEntryId is absent).
	// (PATCH /playlists/{playlistId}/items/{entryId})
	MovePlaylistItem(w http.ResponseWriter, r *http.Request, playlistId PlaylistId, entryId int64)
	// GetPlexImport Whether a Plex database is available, import progress and the last report (admin only).
	// (GET /plex-import)
	GetPlexImport(w http.ResponseWriter, r *http.Request)
	// StartPlexImport Start an import in the background (admin only). Safe to run again; nothing is duplicated.
	// (POST /plex-import)
	StartPlexImport(w http.ResponseWriter, r *http.Request)
	// PreviewPlexImport Read a snapshot of the Plex database and show what an import would do (admin only).
	// (POST /plex-import/preview)
	PreviewPlexImport(w http.ResponseWriter, r *http.Request)
	// ListProfiles Profiles that can be switched to from this device (Plex Home equivalent).
	// (GET /profiles)
	ListProfiles(w http.ResponseWriter, r *http.Request)
	// SwitchProfile Switch this device to another profile. Requires that profile's PIN (or password if it has no PIN).
	// (POST /profiles/{userId}/switch)
	SwitchProfile(w http.ResponseWriter, r *http.Request, userId UserId)
	// Search Search titles across the libraries the user can access.
	// (GET /search)
	Search(w http.ResponseWriter, r *http.Request, params SearchParams)
	// GetSettings Server settings (admin only). Secret values are never returned, only whether they are set.
	// (GET /settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSettings Partially update settings (admin only). Omitted sections and fields are unchanged.
	// (PATCH /settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request)
	// CompleteSetup First-run setup. Creates the admin account. Only allowed while setupRequired is true.
	// (POST /setup)
	CompleteSetup(w http.ResponseWriter, r *http.Request)
	// GetHealth Liveness/readiness probe.
	// (GET /system/health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetSystemInfo Public server identity and status (used for discovery and connection checks).
	// (GET /system/info)
	GetSystemInfo(w http.ResponseWriter, r *http.Request)
	// RestartServer Restart the server (admin only). Docker brings it back up.
	// (POST /system/restart)
	RestartServer(w http.ResponseWriter, r *http.Request)
	// SystemStatus Server health for the dashboard (admin only).
	// (GET /system/status)
	SystemStatus(w http.ResponseWriter, r *http.Request)
	// ListTasks Scheduled maintenance tasks and their last run (admin only).
	// (GET /tasks)
	ListTasks(w http.ResponseWriter, r *http.Request)
	// RunTask Run a task now (admin only).
	// (POST /tasks/{taskId}/run)
	RunTask(w http.ResponseWriter, r *http.Request, taskId string)
	// ListUsers All users (admin only).
	// (GET /users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// CreateUser Create a user or managed profile (admin only).
	// (POST /users)
	CreateUser(w http.ResponseWriter, r *http.Request)
	// DeleteUser Delete a user and their devices, watch history and playlists (admin only). The last admin cannot be deleted.
	// (DELETE /users/{userId})
	DeleteUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// UpdateUser Update a user (admin only). Omitted fields are unchanged.
	// (PATCH /users/{userId})
	UpdateUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// DeleteAvatar Remove a profile picture (yourself, or any user as an administrator).
	// (DELETE /users/{userId}/avatar)
	DeleteAvatar(w http.ResponseWriter, r *http.Request, userId UserId)
	// GetAvatar A user's profile picture (512×512 JPEG). Available without signing in where the sign-in profile picker is shown.
	// (GET /users/{userId}/avatar)
	GetAvatar(w http.ResponseWriter, r *http.Request, userId UserId, params GetAvatarParams)
	// SetAvatar Upload a profile picture (yourself, or any user as an administrator). JPEG, PNG or WebP up to 10 MB; it is center-cropped to a square and stored at 512×512.
	// (PUT /users/{userId}/avatar)
	SetAvatar(w http.ResponseWriter, r *http.Request, userId UserId)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandlerFunc   func(w http.ResponseWriter, r *http.Request, err error)
}

type MiddlewareFunc func(http.Handler) http.Handler

// GetActivity operation middleware
func (siw *ServerInterfaceWrapper) GetActivity(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.GetActivity(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

// PlayHistory operation middleware
func (siw *ServerInterfaceWrapper) PlayHistory(w http.ResponseWriter, r *http.Request) {

	var err error
	_ = err

	// Parameter object where we will unmarshal all parameters from the context
	var params PlayHistoryParams

	// ------------- Optional query parameter "limit" -------------

	err = runtime.BindQueryParameterWithOptions("form", true, false, "limit", r.URL.Query(), &params.Limit, runtime.BindQueryParameterOptions{Type: "integer", Format: ""})
	if err != nil {
		var requiredError *runtime.RequiredParameterError
		if errors.As(err, &requiredError) {
			siw.ErrorHandlerFunc(w, r, &RequiredParamError{ParamName: "limit"})
		} else {
			siw.ErrorHandlerFunc(w, r, &InvalidParamFormatError{ParamName: "limit", Err: err})
		}
		return
	}

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.PlayHistory(w, r, params)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

